data.query:
query ProjectMilestones($first: Int, $after: String) {
    projectMilestones(first: $first, after: $after) {
        nodes {
            id
            name
            description
            targetDate
            createdAt
            updatedAt
            project {
                id
            }
        }
        pageInfo {
            hasNextPage
            endCursor
        }
    }
}
